"""Strict JSON decoding shared by the persistent registries.

The only difference from :func:`json.loads` is that number tokens whose
lexical form is a negative zero (``-0``, ``-0.0``, ``-0e2`` ...) are rejected.
``json.loads`` silently normalizes ``-0`` to the integer ``0`` and ``-0.0``
to a non-negative float, which would let two byte-different files compare
equal; the registries instead treat such literals as malformed input. The
hooks only see number tokens, so a ``-0`` appearing inside a string is never
inspected.
"""

from __future__ import annotations

import json

__all__ = ["strict_loads"]


def _is_negative_zero(token: str) -> bool:
    body = token.lstrip()
    if not body.startswith("-"):
        return False
    # A signed numeric token is negative zero exactly when its value is zero;
    # -0.5 stays non-zero, while every spelling of -0 (fraction/exponent) maps
    # to zero.
    return float(body) == 0.0


def _parse_int(token: str) -> int:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return int(token)


def _parse_float(token: str) -> float:
    if _is_negative_zero(token):
        raise ValueError("negative-zero number literal is not allowed")
    return float(token)


def strict_loads(text: str) -> object:
    """Parse JSON, raising ValueError on negative-zero number literals."""
    return json.loads(text, parse_int=_parse_int, parse_float=_parse_float)

_STAGES = ("pending", "execute", "complete", "fault")
_TERMINAL_STAGES = ("complete", "fault", "execute")


def _is_plain_int(value: object) -> bool:
    # bool is a subclass of int and must be rejected.
    return isinstance(value, int) and not isinstance(value, bool)


def _validate_record(data: object) -> dict[str, object]:
    if not isinstance(data, dict) or set(data.keys()) != set(_RECORD_FIELDS):
        raise ValueError("operation audit record must be an object with "
                         "keys op, target, key, stage, changed and error")
    if data["op"] != "restore":
        raise ValueError("operation audit record op must be restore")
    for field in ("target", "key"):
        if not isinstance(data[field], str) or not data[field]:
            raise ValueError(f"operation audit record {field} must be a "
                             "non-empty string")
    stage = data["stage"]
    if stage not in _STAGES:
        raise ValueError(
            "operation audit record stage must be pending, execute, "
            "complete or fault")
    changed = data["changed"]
    error = data["error"]
    if stage == "complete":
        if not isinstance(changed, bool):
            raise ValueError("a complete record must carry a boolean changed")
        if error is not None:
            raise ValueError("a complete record must not carry an error")
    elif stage == "fault":
        if changed is not None:
            raise ValueError("a fault record must not carry changed")
        if not isinstance(error, str) or not error:
            raise ValueError("a fault record must carry a non-empty error")
    else:
        if changed is not None or error is not None:
            raise ValueError(
                "a pending or execute record must carry null changed "
                "and error")
    return {field: data[field] for field in _RECORD_FIELDS}


def _validate_document(data: object) -> dict[str, object]:
    if not isinstance(data, dict) or set(data.keys()) != set(_ROOT_FIELDS):
        raise ValueError("operation audit root must be an object with "
                         "keys version and operations")
    version = data["version"]
    if not _is_plain_int(version) or version != _VERSION:
        raise ValueError("unsupported operation audit version")
    raw_operations = data["operations"]
    if not isinstance(raw_operations, dict):
        raise ValueError("operation audit operations must be an object")
    if list(raw_operations) != sorted(raw_operations):
        raise ValueError(
            "operation audit operations must be ordered by key code point")
    operations: dict[str, dict[str, object]] = {}
    for key, record in raw_operations.items():
        if not isinstance(key, str) or not key:
            raise ValueError("operation audit keys must be non-empty strings")
        operations[key] = _validate_record(record)
    return {"version": _VERSION, "operations": operations}


def _read_locked(audit_realpath: str) -> dict[str, object] | None:
    # Read the audit bytes while the caller holds its companion lock.
    # The audit file is created on demand, so a missing file simply means
    # no operation has been journaled yet; parsing and validation run on
    # the locked bytes.
    try:
        with open(audit_realpath, encoding="utf-8") as handle:
            text = handle.read()
    except FileNotFoundError:
        return None
    try:
        data = strict_loads(text)
    except ValueError as exc:
        raise ValueError(
            f"operation audit file {audit_realpath!r} is not valid JSON"
            ) from exc
    return _validate_document(data)


def _record(stage: str, target_realpath: str, key: str,
            *, changed: bool | None = None,
            error: str | None = None) -> dict[str, object]:
    return {
        "op": "restore",
        "target": target_realpath,
        "key": key,
        "stage": stage,
        "changed": changed,
        "error": error,
    }


def _write_record(audit_realpath: str, target_realpath: str, key: str,
                  stage: str, *, changed: bool | None = None,
                  error: str | None = None) -> None:
    # Validate/update/replace under one exclusive hold on the audit's
    # companion lock (restore already holds the target lock around this),
    # so a shared-lock get can only observe the whole audit from before
    # or after the update. Operations are re-emitted in key code-point
    # order and a repeated key overwrites the same entry. Encoding, the
    # atomic replace and both fsyncs follow the history files exactly.
    with _recover_all._history_file_lock(audit_realpath):
        document = _read_locked(audit_realpath)
        if document is None:
            document = {"version": _VERSION, "operations": {}}
        operations = document["operations"]
        operations[key] = _record(stage, target_realpath, key,
                                  changed=changed, error=error)
        ordered = {"version": _VERSION,
                   "operations": {name: operations[name]
                                  for name in sorted(operations)}}
        _recover_all._atomic_write(audit_realpath, ordered)


def _record_pending(target_realpath: str, key: str) -> None:
    # Journal the call before it does anything. A write failure (an
    # OSError from the temp file, replace or fsync) propagates and the
    # caller must not start the restore.
    _write_record(target_realpath + ".audit", target_realpath, key,
                  "pending")


def _record_terminal(target_realpath: str, key: str, stage: str,
                     *, changed: bool | None = None,
                     error: str | None = None) -> None:
    # Replace the pending record with its terminal state. A write
    # failure leaves the pending record in place and propagates OSError.
    if stage not in _TERMINAL_STAGES:
        raise ValueError("terminal audit stage must be complete, fault "
                         "or execute")
    _write_record(target_realpath + ".audit", target_realpath, key, stage,
                  changed=changed, error=error)


def get(target: str, key: str) -> dict[str, object]:
    """Return the audit record journaled for ``key`` on ``target``.

    Both arguments must be non-empty strings, else ``ValueError`` -- the
    same argument, file and I/O rules :func:`carbon_market.history.get`
    follows. The audit file is read under a shared flock on
    ``target + ".audit.lock"`` while it is opened and read; malformed
    JSON, a negative-zero literal, or an unsupported version or
    structure raises ``ValueError`` and any other locking or I/O failure
    raises ``OSError``. An audit file that does not exist yet holds no
    records, so an unknown key -- there exactly as in a present file --
    raises ``KeyError(key)``.

    On success the result carries keys op, target, key, stage, changed
    and error, in that order: ``op`` is ``"restore"``, ``stage`` is
    ``"pending"``, ``"execute"``, ``"complete"`` or ``"fault"``,
    ``changed`` is the restore's boolean only for a complete record and
    ``error`` the exception class name only for a fault record; every
    other field is null. The query never writes.
    """
    for value in (target, key):
        if not isinstance(value, str) or not value:
            raise ValueError("target and key must be non-empty strings")

    target_realpath = os.path.realpath(target)
    audit_realpath = target_realpath + ".audit"
    with _recover_all._history_file_lock(audit_realpath, shared=True):
        document = _read_locked(audit_realpath)

    if document is None or key not in document["operations"]:
        raise KeyError(key)
    return {field: document["operations"][key][field]
            for field in _RECORD_FIELDS}
